param([string]$RemoteHost='h200-codex',[string]$RemoteRoot='/home/hera/pid_reliability_benchmark/outputs/final_degradation',[string]$LocalRoot='outputs/final_degradation')
$ErrorActionPreference='Stop';$files=@('qwen8_set_b_clean.jsonl','qwen8_set_b_blur_r1.jsonl','qwen8_set_b_blur_r2.jsonl','qwen8_set_b_blur_r4.jsonl','qwen8_set_b_jpeg_q70.jsonl','qwen8_set_b_jpeg_q35.jsonl','qwen8_set_b_jpeg_q15.jsonl','qwen8_set_b_downsample_s075.jsonl','qwen8_set_b_downsample_s050.jsonl','qwen8_set_b_downsample_s025.jsonl');$ssh=Join-Path $env:WINDIR 'System32/OpenSSH/ssh.exe';$localDir=Join-Path (Get-Location) $LocalRoot;[IO.Directory]::CreateDirectory($localDir)|Out-Null
foreach($file in $files){$rp="$RemoteRoot/$file";$si=New-Object Diagnostics.ProcessStartInfo;$si.FileName=$ssh;$si.Arguments="-o BatchMode=yes $RemoteHost `"base64 -w0 $rp`"";$si.UseShellExecute=$false;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true;$p=New-Object Diagnostics.Process;$p.StartInfo=$si;[void]$p.Start();$enc=$p.StandardOutput.ReadToEnd();$err=$p.StandardError.ReadToEnd();$p.WaitForExit();if($p.ExitCode -ne 0){throw "pull failed $file $err"};$bytes=[Convert]::FromBase64String(($enc -replace '\s',''));[IO.File]::WriteAllBytes((Join-Path $localDir $file),$bytes);Write-Output("pulled {0} bytes={1}" -f $file,$bytes.Length)}
